module div_8bit (
    input wire clk,
    input wire rst,
    input wire [7:0] dividend,
    input wire [7:0] divisor,
    input wire sign,
    input wire opn_valid,
    output reg res_valid,
    input wire res_ready,
    output wire [15:0] result
);
    reg res_valid_reg;
    reg start_cnt;
    reg [3:0] cnt;
    reg [7:0] neg_divisor;
    reg [7:0] remainder;
    reg [7:0] quotient;
    reg [15:0] SR;
    assign result = SR;
    assign res_valid = res_valid_reg;
    always @(*) begin
        if(!rst && !res_valid_reg && opn_valid) begin
            if(sign==1'b1) begin
                if(dividend[7]==1'b1) begin
                    remainder = (~dividend)+1;
                end
                else begin
                    remainder = dividend;
                end

                if(divisor[7]==1'b1) begin
                    neg_divisor = (~divisor)+1;
                end
                else begin
                    neg_divisor = divisor;
                end
            end
            else begin
                remainder = dividend;
                neg_divisor = divisor;
            end

            quotient = 0;
            SR = {remainder, 1'b0};
        end

        else if(start_cnt) begin
            if(cnt[3]==1'b1) begin
                cnt = 0;
                start_cnt = 0;
                SR = {remainder, quotient};
            end
            else begin
                cnt = cnt + 1;
                remainder = remainder-neg_divisor;
                quotient = quotient << 1;
                quotient[cnt] = (remainder>=0)?1'b1:1'b0;
                remainder = (remainder>=0)?remainder:(remainder+divisor);
            end
        end
    end

    always @(posedge clk or posedge rst) begin
        if(rst) begin
            res_valid_reg <= 1'b0;
        end
        else if(cnt==4'd8||res_ready) begin
            res_valid_reg <= 1'b0;
        end
        else begin
            res_valid_reg <= res_valid_reg;
        end
    end
endmodule
